import React, { useState, useRef } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faPhoneAlt, faEnvelope, faLink } from '@fortawesome/free-solid-svg-icons';
import { motion } from 'framer-motion';
import CustomHook from './CustomHook';

export default function Contacts() {
  const divs = useRef([]);
  const scrollTab = useRef();
  divs.current = [];

  const attachRef = (el) => {
    if (el && !divs.current.includes(el)) divs.current.push(el);
  };

  const [listContacts] = useState([
    {
      title: 'Phone',
      value: '+91 9079289874',
      href: 'tel:+919079289874',
      icon: faPhoneAlt,
      aria: 'Call Punit Gupta',
    },
    {
      title: 'Email',
      value: 'punitg505@gmail.com',
      href: 'mailto:punitg505@gmail.com',
      icon: faEnvelope,
      aria: 'Email Punit Gupta',
    },
    {
      title: 'LinkedIn',
      value: 'linkedin.com/in/punit-gupta-18a930255',
      href: 'https://www.linkedin.com/in/punit-gupta-18a930255',
      icon: faLink,
      aria: 'Punit Gupta on LinkedIn',
    },
  ]);

  CustomHook(scrollTab, divs);

  // Framer Motion variants
  const container = {
    hidden: { opacity: 0, y: 18 },
    visible: (i = 1) => ({
      opacity: 1,
      y: 0,
      transition: { delay: 0.08 * i, duration: 0.5, ease: 'easeOut' },
    }),
  };

  const iconVariant = {
    hidden: { scale: 0.85, opacity: 0 },
    visible: { scale: 1, opacity: 1, transition: { type: 'spring', stiffness: 260, damping: 20 } },
    hover: { scale: 1.06, transition: { yoyo: Infinity, duration: 0.9 } }, // subtle pulse if you want continuous
  };

  return (
    <section
      className="contacts py-10 px-6 sm:px-10 bg-gray-900 text-gray-100"
      ref={scrollTab}
      aria-label="Contact Information"
    >
      <div className="max-w-6xl mx-auto" ref={attachRef}>
        <motion.div
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.2 }}
          className="title mb-6"
        >
          <motion.h2 variants={container} className="text-3xl font-bold tracking-tight text-white">
            Contact Me
          </motion.h2>
          <motion.p
            variants={container}
            className="text-gray-400 mt-2 max-w-2xl"
            custom={2}
          >
            Feel free to reach out for collaborations, internships, or technical discussions.
          </motion.p>
        </motion.div>

        <div className="list grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
          {listContacts.map((item, idx) => (
            <motion.article
              key={idx}
              ref={attachRef}
              className="item flex items-start gap-4 p-5 rounded-xl bg-gray-800 border border-gray-700 hover:border-blue-500 transition duration-300"
              initial="hidden"
              whileInView="visible"
              viewport={{ once: true, amount: 0.2 }}
              custom={idx + 1}
              variants={container}
              role="listitem"
            >
              <motion.div
                className="icon w-12 h-12 flex items-center justify-center rounded-full bg-blue-600/10 text-blue-400 text-lg"
                variants={iconVariant}
                initial="hidden"
                whileInView="visible"
                whileHover={{ scale: 1.08 }}
              >
                <FontAwesomeIcon icon={item.icon} />
              </motion.div>

              <div className="content">
                <h3 className="text-sm font-semibold text-gray-300">{item.title}</h3>
                <motion.a
                  href={item.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  aria-label={item.aria}
                  className="block mt-1 text-blue-400 hover:underline break-all"
                  whileHover={{ x: 4 }}
                >
                  {item.value}
                </motion.a>
              </div>
            </motion.article>
          ))}
        </div>
      </div>
    </section>
  );
}
